"""Import an offline MusicBrainz core-data export into the Nix catalog."""

import csv
from pathlib import Path
from uuid import UUID


def import_musicbrainz_tsv(path: str) -> list[dict]:
    """Read the TSV generated by musicbrainz_export.sql."""
    works = []
    with Path(path).open(encoding="utf-8", newline="") as source:
        reader = csv.DictReader(source, delimiter="\t")
        required = {"kind", "mbid", "title", "artist", "album", "year"}
        if not required.issubset(reader.fieldnames or []):
            raise ValueError(f"{path}: expected columns {', '.join(sorted(required))}")
        for row in reader:
            kind = row["kind"]
            title = row["title"]
            if kind not in ("album", "track") or not title:
                raise ValueError(f"{path}:{reader.line_num}: invalid kind or title")
            mbid = str(UUID(row["mbid"]))
            id_type = "release_group" if kind == "album" else "recording"
            works.append({
                "id": f"nix:work:{kind}:musicbrainz:{mbid}",
                "kind": kind,
                "title": title,
                "original_title": row["album"] or None,
                "creators": row["artist"] or None,
                "release_year": int(row["year"]) if row["year"] else None,
                "cover_thumb": "placeholder:vinyl_grooves",
                "external_ids": {f"musicbrainz_{id_type}": mbid},
            })
    return works
